INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, session, is_shortlisted) VALUES ('talk', 'myth-making-in-new-nature', 'ProtFiSIG', 'Myth-Making in New Nature', 'How to turn classic legends, myths, and folktales into protocol stories. How to balance newness while pulling from preexisting stories, and how to use folklore to explore the world of protocols. Using a practitioner-model, this session will show participants how a Protoclized/Jamverse writers move from idea all the way to published story.', 'Liz Maher', 'lizmaherland@gmail.com', 'Protocol Fiction', 1);
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, speaker_website, artifact_type, session, is_shortlisted) VALUES ('talk', 'story-shaping-in-new-nature', 'ProtFiSIG', 'Story-Shaping in New Nature', 'In this talk, we''ll explore how protocol fiction authors can use an array of techniques from both foresight and game design practices to build rich and nuanced worlds. The foresight field has powerful tools for investigating possible futures of complex systems and for generating evocative scenarios. Indie storytelling games have developed a wide breadth of approaches to evolving coherent and compelling worlds. By the end of this talk, you''ll be ready to leverage these approaches to shape compelling settings for your own protocol fictions.', 'Spencer Nitkey', 'spencernitkeywriting@gmail.com', 'spencernitkey.com', 'Other type of artifact (eg: demo, website, etc.)', 'Protocol Fiction', 1);
INSERT INTO symposium_proposals (type, slug, track, title, abstract, speaker_name, speaker_email, co_speakers, session, is_shortlisted) VALUES ('interactive', 'creating-new-genres-for-new-nature', 'ProtFiSIG', 'Creating New Genres for New Nature', 'Walter Benjamin wrote that "All great works of literature either dissolve a genre or invent one." In this interactive session, participants will learn the components and theories of genre — including a brief survey of Protocol Fiction — and then experiment with creating their own sub-genre using a scaffolded interactive genre-building process. Using the 4 Jamverse founding worlds as examples, participants will wield the skills gained in the first two talks to outline their own "PF subgenre" set in the Jamverse. Contributions from the session may even be installed into the Jamverse or lay the groundwork for future Protocolized stories.', 'Spencer Nitkey', 'spencernitkeywriting@gmail.com', 'Sachin Benny', 'Protocol Fiction', 1);
